      hu: ["Naponta több millió liter tejet dolgoz fel.", "Tejport állít elő exportra.", "Fontos munkáltató a régióban."],
      ro: ["Procesează zilnic milioane de litri de lapte.", "Produce lapte praf pentru export.", "Angajator important în regiune."],
      en: ["Processes millions of liters of milk daily.", "Produces milk powder for export.", "Major employer in the region."],
      es: ["Procesa millones de litros de leche diariamente.", "Produce leche en polvo para la exportación.", "Importante empleador en la región."],
      pt: ["Processa milhões de litros de leite diariamente.", "Produz leite em pó para exportação.", "Importante empregador na região."],
      fr: ["Traite des millions de litres de lait chaque jour.", "Produit du lait en poudre pour l'exportation.", "Employeur important dans la région."],
